public class Solution {
    public IList<string> Autocomplete(string[] words, int[] weights, string prefix, int k) {
        var matches = new List<(string word, int weight)>();
        for (int i = 0; i < words.Length; i++) {
            if (words[i].StartsWith(prefix)) {
                matches.Add((words[i], weights[i]));
            }
        }
        var sorted = matches.OrderByDescending(m => m.weight).ToList();
        return sorted.Take(k).Select(m => m.word).ToList();
    }
}

