func autocomplete(words []string, weights []int, prefix string, k int) []string {
    type pair struct{ word string; weight int }
    var matches []pair
    for i, w := range words {
        if strings.HasPrefix(w, prefix) {
            matches = append(matches, pair{w, weights[i]})
        }
    }
    sort.Slice(matches, func(i, j int) bool {
        return matches[i].weight > matches[j].weight
    })
    if k > len(matches) {
        k = len(matches)
    }
    res := make([]string, k)
    for i := 0; i < k; i++ {
        res[i] = matches[i].word
    }
    return res
}

