public class AutocompleteSystem {
    private class TrieNode {
        public Dictionary<char, TrieNode> Children = new();
        public List<(string word, int weight)> Suggestions = new();
    }
    private readonly TrieNode _root = new();
    private readonly int _k;

    public AutocompleteSystem(string[] words, int[] weights, int k) {
        _k = k;
        for (int i = 0; i < words.Length; i++) {
            Insert(words[i], weights[i]);
        }
    }

    private void Insert(string word, int weight) {
        TrieNode node = _root;
        foreach (char c in word) {
            if (!node.Children.ContainsKey(c))
                node.Children[c] = new TrieNode();
            node = node.Children[c];
            // Atualiza sugestões
            node.Suggestions.Add((word, weight));
            node.Suggestions = node.Suggestions.OrderByDescending(x => x.weight).Take(_k).ToList();
        }
    }

    public List<string> Autocomplete(string prefix) {
        TrieNode node = _root;
        foreach (char c in prefix) {
            if (!node.Children.ContainsKey(c)) return new List<string>();
            node = node.Children[c];
        }
        return node.Suggestions.Select(s => s.word).ToList();
    }
}

