type AutocompleteSystem struct {
    root *TrieNode
    k    int
}

func Constructor(words []string, weights []int, k int) AutocompleteSystem {
    as := AutocompleteSystem{root: &TrieNode{children: make(map[rune]*TrieNode)}, k: k}
    for i, w := range words {
        as.insert(w, weights[i])
    }
    return as
}

func (as *AutocompleteSystem) insert(word string, weight int) {
    node := as.root
    for _, ch := range word {
        if node.children[ch] == nil {
            node.children[ch] = &TrieNode{children: make(map[rune]*TrieNode)}
        }
        node = node.children[ch]
        // manter top k
        node.suggestions = append(node.suggestions, struct{ word string; weight int }{word, weight})
        sort.Slice(node.suggestions, func(i, j int) bool {
            return node.suggestions[i].weight > node.suggestions[j].weight
        })
        if len(node.suggestions) > as.k {
            node.suggestions = node.suggestions[:as.k]
        }
    }
}

func (as *AutocompleteSystem) Autocomplete(prefix string) []string {
    node := as.root
    for _, ch := range prefix {
        if node.children[ch] == nil {
            return []string{}
        }
        node = node.children[ch]
    }
    res := make([]string, len(node.suggestions))
    for i, s := range node.suggestions {
        res[i] = s.word
    }
    return res
}

