class AutocompleteSystem {
    class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        List<Pair> suggestions = new ArrayList<>();
    }
    class Pair { String word; int weight; Pair(String w, int wt) { word = w; weight = wt; } }

    private TrieNode root = new TrieNode();
    private int k;

    public AutocompleteSystem(String[] words, int[] weights, int k) {
        this.k = k;
        for (int i = 0; i < words.length; i++) {
            insert(words[i], weights[i]);
        }
    }

    private void insert(String word, int weight) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            node.children.putIfAbsent(c, new TrieNode());
            node = node.children.get(c);
            node.suggestions.add(new Pair(word, weight));
            node.suggestions.sort((a, b) -> b.weight - a.weight);
            if (node.suggestions.size() > k) node.suggestions.remove(node.suggestions.size() - 1);
        }
    }

    public List<String> autocomplete(String prefix) {
        TrieNode node = root;
        for (char c : prefix.toCharArray()) {
            if (!node.children.containsKey(c)) return List.of();
            node = node.children.get(c);
        }
        return node.suggestions.stream().map(p -> p.word).collect(Collectors.toList());
    }
}

